import { normalize } from './normalize'
import type { Lang } from './languages'

/**
 * Emoji search for the icon picker: Unicode CLDR names and keywords in English and the app's
 * language. The name files (src/lib/emoji-names/<lang>.js, generated by scripts/build-emoji.mjs)
 * are separate assets fetched on first search, so they stay out of the single inlined bundle; the
 * service worker caches them like the other app assets. They hold JSON, fetched and parsed, never
 * run; .js because Nextcloud does not serve .json files from app folders.
 */
const URLS = import.meta.glob<string>('./emoji-names/*.js', { eager: true, query: '?url', import: 'default' })

/** emoji → normalized "name|keyword|…" */
type Names = Record<string, string>

const loaded = new Map<string, Promise<Names>>()

function loadNames(code: string): Promise<Names> {
	let p = loaded.get(code)
	if (!p) {
		const url = URLS[`./emoji-names/${code}.js`]
		p = (url ? fetch(url).then((r) => (r.ok ? r.json() : {})) : Promise.resolve({}))
			.then((raw: Names) => {
				const out: Names = {}
				for (const [e, text] of Object.entries(raw)) out[e] = text.split('|').map(normalize).join('|')
				return out
			})
			.catch(() => {
				loaded.delete(code) // offline on first use: try again next time
				return {}
			})
		loaded.set(code, p)
	}
	return p
}

/** Searchable text per emoji in English plus `lang`. */
export async function emojiNames(lang: Lang): Promise<Names> {
	const sets = await Promise.all([...new Set<string>(['en', lang])].map(loadNames))
	const out: Names = {}
	for (const set of sets) {
		for (const [e, text] of Object.entries(set)) out[e] = out[e] ? out[e] + '|' + text : text
	}
	return out
}

/** Scripts without spaces between words: match anywhere, not just at word starts. */
const NO_SPACES = /[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]/u

/**
 * How well `text` (from emojiNames) matches the query terms: lower is better, null = no match.
 * Every term must match the start of a word (or anywhere for Japanese); a name that starts with
 * the query ranks first.
 */
function score(text: string, terms: string[], query: string): number | null {
	const words = text.split(/[| ]/)
	let total = 0
	for (const term of terms) {
		if (words.some((w) => w === term)) continue
		if (words.some((w) => w.startsWith(term))) { total += 1; continue }
		if (NO_SPACES.test(term) && text.includes(term)) { total += 2; continue }
		return null
	}
	const name = text.split('|')
	if (name.some((n) => n === query)) return total - 3
	if (name.some((n) => n.startsWith(query))) return total - 2
	return total
}

/** Emoji from `candidates` (in picker order) matching `query`, best matches first. */
export function searchEmoji(names: Names, candidates: string[], query: string): string[] {
	const q = normalize(query)
	if (!q) return []
	const terms = q.split(' ')
	const hits: { e: string, s: number, i: number }[] = []
	candidates.forEach((e, i) => {
		const text = names[e]
		const s = text ? score(text, terms, q) : null
		if (s !== null) hits.push({ e, s, i })
	})
	return hits.sort((a, b) => a.s - b.s || a.i - b.i).map((h) => h.e)
}
